#include <cassert>
#include <iostream>
#include "mesh/journal.h"
int main(){fs::FS storage;matter::Journal journal;journal.begin(storage);matter::Record sent;sent.token=0xab;sent.mine=true;sent.body="Original reply text";sent.repeaters=1;sent.heard="aa";assert(journal.append(sent));matter::Journal initial;initial.begin(storage);assert(initial.records[0].heard=="aa");assert(journal.repeats(sent.token,2,"ab,cd"));assert(journal.update(sent.token,"Sent / no group ACK"));matter::Journal reboot;reboot.begin(storage);assert(reboot.records.size()==1&&reboot.records[0].heard=="ab,cd"&&reboot.records[0].repeaters==2&&reboot.records[0].body==sent.body);assert(reboot.repeats(sent.token,2,"ab,ef"));matter::Journal changed;changed.begin(storage);assert(changed.records[0].heard=="ab,ef");auto file=storage.open("/mattermesh/messages.tsv",FILE_APPEND);file.print("R1\tbc\t0\t1\t0\t-1\tYOU\t*\tSent\tOld message\nC1\tbc\t3\n");matter::Journal legacy;legacy.begin(storage);assert(legacy.records.size()==2&&legacy.records[1].repeaters==3&&legacy.records[1].heard.empty());assert(!legacy.repeats(0xdead,1,"aa"));std::cout<<"PASS: repeater hashes persist across reload, updates with unchanged count, original body retained, legacy R1/C1 compatibility and missing token rejection\n";}
